42	// WriteCommitted writes a committed checkpoint to the entire/checkpoints/v1 branch.
43	// Checkpoints are stored at sharded paths: <id[:2]>/<id[2:]>/
44	//
45	// For task checkpoints (IsTask=true), additional files are written under tasks/<tool-use-id>/:
46	//   - For incremental checkpoints: checkpoints/NNN-<tool-use-id>.json
47	//   - For final checkpoints: checkpoint.json and agent-<agent-id>.jsonl
48	func (s *GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
49		// Validate identifiers to prevent path traversal and malformed data
50		if opts.CheckpointID.IsEmpty() {
51			return errors.New("invalid checkpoint options: checkpoint ID is required")
52		}
53		if err := validation.ValidateSessionID(opts.SessionID); err != nil {
54			return fmt.Errorf("invalid checkpoint options: %w", err)
55		}
56		if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
57			return fmt.Errorf("invalid checkpoint options: %w", err)
58		}
59		if err := validation.ValidateAgentID(opts.AgentID); err != nil {
60			return fmt.Errorf("invalid checkpoint options: %w", err)
61		}
62	
63		// Ensure sessions branch exists
64		if err := s.ensureSessionsBranch(ctx); err != nil {
65			return fmt.Errorf("failed to ensure sessions branch: %w", err)
66		}
67	
68		// Get branch ref and root tree hash (O(1), no flatten)
69		parentHash, rootTreeHash, err := s.getSessionsBranchRef()
70		if err != nil {
71			return err
72		}
73	
74		// Use sharded path: <id[:2]>/<id[2:]>/
75		basePath := opts.CheckpointID.Path() + "/"
76		checkpointPath := opts.CheckpointID.Path()
77	
78		// Flatten only the checkpoint subtree (O(files in checkpoint))
79		entries, err := s.flattenCheckpointEntries(rootTreeHash, checkpointPath)
80		if err != nil {
81			return err
82		}
83	
84		// Track task metadata path for commit trailer
85		var taskMetadataPath string
86	
87		// Handle task checkpoints
88		if opts.IsTask && opts.ToolUseID != "" {
89			taskMetadataPath, err = s.writeTaskCheckpointEntries(ctx, opts, basePath, entries)
90			if err != nil {
91				return err
92			}
93		}
94	
95		// Write standard checkpoint entries (transcript, prompts, context, metadata)
96		if err := s.writeStandardCheckpointEntries(ctx, opts, basePath, entries); err != nil {
97			return err
98		}
99	
100		// Build checkpoint subtree and splice into root (O(depth) tree surgery)
101		newTreeHash, err := s.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
102		if err != nil {
103			return err
104		}
105	
106		commitMsg := s.buildCommitMessage(opts, taskMetadataPath)
107		newCommitHash, err := s.createCommit(newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
108		if err != nil {
109			return err
110		}
111	
112		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
113		newRef := plumbing.NewHashReference(refName, newCommitHash)
114		if err := s.repo.Storer.SetReference(newRef); err != nil {
115			return fmt.Errorf("failed to set branch reference: %w", err)
116		}
117	
118		return nil
119	}
