121	// flattenCheckpointEntries reads only the entries under a specific checkpoint path
122	// from the sessions branch tree. This is O(files in checkpoint) instead of O(all checkpoints).
123	// Returns an empty map if the checkpoint doesn't exist yet.
124	func (s *GitStore) flattenCheckpointEntries(rootTreeHash plumbing.Hash, checkpointPath string) (map[string]object.TreeEntry, error) {
125		entries := make(map[string]object.TreeEntry)
126		if rootTreeHash == plumbing.ZeroHash {
127			return entries, nil
128		}
129	
130		rootTree, err := s.repo.TreeObject(rootTreeHash)
131		if err != nil {
132			if errors.Is(err, plumbing.ErrObjectNotFound) {
133				return entries, nil // Tree doesn't exist yet
134			}
135			return nil, fmt.Errorf("failed to read root tree %s: %w", rootTreeHash, err)
136		}
137	
138		subtree, err := rootTree.Tree(checkpointPath)
139		if err != nil {
140			return entries, nil //nolint:nilerr // Checkpoint doesn't exist yet
141		}
142	
143		// Flatten just this subtree with the full path prefix
144		if err := FlattenTree(s.repo, subtree, checkpointPath, entries); err != nil {
145			return nil, err
146		}
147		return entries, nil
148	}
