150	// spliceCheckpointSubtree builds a tree from checkpoint-local entries and installs it
151	// at the correct shard location in the root tree using O(depth) tree surgery.
152	// basePath is like "a3/b2c4d5e6f7/" (with trailing slash).
153	// Returns the new root tree hash.
154	func (s *GitStore) spliceCheckpointSubtree(ctx context.Context, rootTreeHash plumbing.Hash, checkpointID id.CheckpointID, basePath string, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
155		// Convert entries to relative paths (strip basePath prefix)
156		relEntries := make(map[string]object.TreeEntry, len(entries))
157		for path, entry := range entries {
158			relPath := strings.TrimPrefix(path, basePath)
159			if relPath == path {
160				continue // Entry doesn't have the expected prefix
161			}
162			relEntries[relPath] = entry
163		}
164	
165		// Build the checkpoint subtree from relative entries
166		checkpointTreeHash, err := BuildTreeFromEntries(ctx, s.repo, relEntries)
167		if err != nil {
168			return plumbing.ZeroHash, fmt.Errorf("failed to build checkpoint subtree: %w", err)
169		}
170	
171		// Splice into root tree at the shard path using tree surgery
172		// Path: ["a3"] with entry "b2c4d5e6f7" pointing to the checkpoint tree
173		shardPrefix := string(checkpointID[:2])
174		shardSuffix := string(checkpointID[2:])
175		return UpdateSubtree(s.repo, rootTreeHash, []string{shardPrefix}, []object.TreeEntry{
176			{Name: shardSuffix, Mode: filemode.Dir, Hash: checkpointTreeHash},
177		}, UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
178	}
