334	// writeSessionToSubdirectory writes a single session's files to a numbered subdirectory.
335	// Returns the absolute file paths from the git tree root for the sessions map.
336	func (s *GitStore) writeSessionToSubdirectory(ctx context.Context, opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
337		filePaths := SessionFilePaths{}
338	
339		// Clear any existing entries at this path so stale files from a previous
340		// write (e.g. prompt.txt) don't persist on overwrite.
341		for key := range entries {
342			if strings.HasPrefix(key, sessionPath) {
343				delete(entries, key)
344			}
345		}
346	
347		// Write transcript
348		if err := s.writeTranscript(ctx, opts, sessionPath, entries); err != nil {
349			return filePaths, err
350		}
351		filePaths.Transcript = "/" + sessionPath + paths.TranscriptFileName
352		filePaths.ContentHash = "/" + sessionPath + paths.ContentHashFileName
353	
354		// Write prompts
355		if len(opts.Prompts) > 0 {
356			promptContent := redact.String(JoinPrompts(opts.Prompts))
357			blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
358			if err != nil {
359				return filePaths, err
360			}
361			entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
362				Name: sessionPath + paths.PromptFileName,
363				Mode: filemode.Regular,
364				Hash: blobHash,
365			}
366			filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
367		}
368	
369		// Write session-level metadata.json (CommittedMetadata with all fields including initial_attribution)
370		sessionMetadata := CommittedMetadata{
371			CheckpointID:                opts.CheckpointID,
372			SessionID:                   opts.SessionID,
373			Strategy:                    opts.Strategy,
374			CreatedAt:                   time.Now().UTC(),
375			Branch:                      opts.Branch,
376			CheckpointsCount:            opts.CheckpointsCount,
377			FilesTouched:                opts.FilesTouched,
378			Agent:                       opts.Agent,
379			Model:                       opts.Model,
380			TurnID:                      opts.TurnID,
381			IsTask:                      opts.IsTask,
382			ToolUseID:                   opts.ToolUseID,
383			TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
384			CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
385			TranscriptLinesAtStart:      opts.CheckpointTranscriptStart, // Deprecated: kept for backward compat
386			TokenUsage:                  opts.TokenUsage,
387			SessionMetrics:              opts.SessionMetrics,
388			InitialAttribution:          opts.InitialAttribution,
389			PromptAttributions:          opts.PromptAttributionsJSON,
390			Summary:                     redactSummary(opts.Summary),
391			CLIVersion:                  versioninfo.Version,
392		}
393	
394		metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
395		if err != nil {
396			return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
397		}
398		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
399		if err != nil {
400			return filePaths, err
401		}
402		entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
403			Name: sessionPath + paths.MetadataFileName,
404			Mode: filemode.Regular,
405			Hash: metadataHash,
406		}
407		filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
408	
409		return filePaths, nil
410	}
