412	// writeCheckpointSummary writes the root-level CheckpointSummary with aggregated statistics.
413	// sessions is the complete sessions array (already built by the caller).
414	func (s *GitStore) writeCheckpointSummary(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, sessions []SessionFilePaths) error {
415		checkpointsCount, filesTouched, tokenUsage, err :=
416			s.reaggregateFromEntries(basePath, len(sessions), entries)
417		if err != nil {
418			return fmt.Errorf("failed to aggregate session stats: %w", err)
419		}
420	
421		var combinedAttribution *InitialAttribution
422		rootMetadataPath := basePath + paths.MetadataFileName
423		if entry, exists := entries[rootMetadataPath]; exists {
424			existingSummary, readErr := s.readSummaryFromBlob(entry.Hash)
425			if readErr == nil {
426				combinedAttribution = existingSummary.CombinedAttribution
427			}
428		}
429	
430		summary := CheckpointSummary{
431			CheckpointID:        opts.CheckpointID,
432			CLIVersion:          versioninfo.Version,
433			Strategy:            opts.Strategy,
434			Branch:              opts.Branch,
435			CheckpointsCount:    checkpointsCount,
436			FilesTouched:        filesTouched,
437			Sessions:            sessions,
438			TokenUsage:          tokenUsage,
439			CombinedAttribution: combinedAttribution,
440		}
