631	func (s *GitStore) writeTranscript(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
632		logCtx := logging.WithComponent(ctx, "checkpoint")
633		transcriptBytes := opts.Transcript.Bytes()
634	
635		// TranscriptPath fallback: data read from disk is an untrusted source,
636		// so we redact it here. The in-memory path (opts.Transcript) is already
637		// pre-redacted by the caller — enforced by the RedactedBytes type.
638		if len(transcriptBytes) == 0 && opts.TranscriptPath != "" {
639			rawData, readErr := os.ReadFile(opts.TranscriptPath)
640			if readErr != nil {
641				// Non-fatal: transcript may not exist yet
642				rawData = nil
643			}
644			if len(rawData) > 0 {
645				redacted, redactErr := redact.JSONLBytes(rawData)
646				if redactErr != nil {
647					return fmt.Errorf("failed to redact transcript from file: %w", redactErr)
648				}
649				transcriptBytes = redacted.Bytes()
650			}
651		}
652		if len(transcriptBytes) == 0 {
653			return nil
654		}
655	
656		if opts.Agent == agent.AgentTypeCodex {
657			transcriptBytes = codex.SanitizePortableTranscript(transcriptBytes)
658		}
659	
660		// Chunk the transcript if it's too large
661		chunkStart := time.Now()
662		chunkCtx, chunkTranscriptSpan := perf.Start(ctx, "chunk_transcript")
663		chunks, err := agent.ChunkTranscript(chunkCtx, transcriptBytes, opts.Agent)
664		if err != nil {
665			chunkTranscriptSpan.RecordError(err)
666			chunkTranscriptSpan.End()
667			return fmt.Errorf("failed to chunk transcript: %w", err)
668		}
669		chunkTranscriptSpan.End()
670		chunkDuration := time.Since(chunkStart)
671	
672		// Write chunk files
673		blobStart := time.Now()
674		blobCtx, writeTranscriptBlobsSpan := perf.Start(chunkCtx, "write_transcript_blobs")
675		for i, chunk := range chunks {
676			chunkPath := basePath + agent.ChunkFileName(paths.TranscriptFileName, i)
677			blobHash, err := CreateBlobFromContent(s.repo, chunk)
678			if err != nil {
679				writeTranscriptBlobsSpan.RecordError(err)
680				writeTranscriptBlobsSpan.End()
681				return err
682			}
683			entries[chunkPath] = object.TreeEntry{
684				Name: chunkPath,
685				Mode: filemode.Regular,
686				Hash: blobHash,
687			}
688		}
689		writeTranscriptBlobsSpan.End()
690		blobDuration := time.Since(blobStart)

