119	// ReadSession reads a session from Codex's storage (JSONL rollout file).
120	func (c *CodexAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
121		if input.SessionRef == "" {
122			return nil, errors.New("session reference (transcript path) is required")
123		}
124	
125		data, err := os.ReadFile(input.SessionRef)
126		if err != nil {
127			return nil, fmt.Errorf("failed to read transcript: %w", err)
128		}
129	
130		startTime, err := parseSessionStartTime(data)
131		if err != nil {
132			return nil, fmt.Errorf("failed to parse session start time: %w", err)
133		}
134	
135		// Extract modified files from the rollout transcript (best-effort, deduplicated).
136		var modifiedFiles []string
137		seen := make(map[string]struct{})
138		for _, lineData := range splitJSONL(data) {
139			for _, f := range extractFilesFromLine(lineData) {
140				if _, exists := seen[f]; !exists {
141					seen[f] = struct{}{}
142					modifiedFiles = append(modifiedFiles, f)
143				}
144			}
145		}
146	
147		return &agent.AgentSession{
148			SessionID:     input.SessionID,
149			AgentName:     c.Name(),
150			SessionRef:    input.SessionRef,
151			StartTime:     startTime,
152			NativeData:    data,
153			ModifiedFiles: modifiedFiles,
154		}, nil
155	}
