157	// WriteSession writes a session to Codex's storage (JSONL rollout file).
158	func (c *CodexAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
159		if session == nil {
160			return errors.New("session is nil")
161		}
162	
163		if session.AgentName != "" && session.AgentName != c.Name() {
164			return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
165		}
166	
167		if session.SessionRef == "" {
168			return errors.New("session reference (transcript path) is required")
169		}
170	
171		if len(session.NativeData) == 0 {
172			return errors.New("session has no native data to write")
173		}
174	
175		dataToWrite := sanitizeRestoredTranscript(session.NativeData)
176		if err := os.WriteFile(session.SessionRef, dataToWrite, 0o600); err != nil {
177			return fmt.Errorf("failed to write transcript: %w", err)
178		}
179	
180		return nil
181	}
