211	func restoredRolloutPath(codexHome, agentSessionID string, startTime time.Time) string {
212		timestamp := startTime.UTC()
213		datePath := filepath.Join(
214			codexHome,
215			timestamp.Format("2006"),
216			timestamp.Format("01"),
217			timestamp.Format("02"),
218		)
219		filename := fmt.Sprintf("rollout-%s-%s.jsonl", timestamp.Format("2006-01-02T15-04-05"), agentSessionID)
220		return filepath.Join(datePath, filename)
221	}
222	
223	func findRolloutBySessionID(codexHome, agentSessionID string) string {
224		if codexHome == "" || validation.ValidateAgentSessionID(agentSessionID) != nil {
225			return ""
226		}
227	
228		patterns := []string{
229			filepath.Join(codexHome, "rollout-*-"+agentSessionID+".jsonl"),
230			filepath.Join(codexHome, "*", "*", "*", "rollout-*-"+agentSessionID+".jsonl"),
231			filepath.Join(filepath.Dir(codexHome), "archived_sessions", "*", "*", "*", "rollout-*-"+agentSessionID+".jsonl"),
232		}
233		for _, pattern := range patterns {
234			matches, err := filepath.Glob(pattern)
235			if err != nil || len(matches) == 0 {
236				continue
237			}
238			// Multiple restored rollouts for the same session ID can exist. Return the
239			// lexicographically latest path so newer dated restores win deterministically.
240			sort.Strings(matches)
241			return matches[len(matches)-1]
242		}
243	
244		return ""
245	}
