998	// updateCombinedAttributionForCheckpoint computes holistic attribution across all sessions.
999	// Instead of summing per-session numbers (which inflates totals because each session
1000	// independently counts the full commit), this diffs parent→HEAD once and classifies
1001	// lines as agent or human based on the union of all sessions' files_touched.
1002	func (s *ManualCommitStrategy) updateCombinedAttributionForCheckpoint(
1003		ctx context.Context,
1004		repo *git.Repository,
1005		checkpointID id.CheckpointID,
1006		headTree, parentTree *object.Tree,
1007		repoDir string,
1008	) error {
1009		logCtx := logging.WithComponent(ctx, "attribution")
1010		store := checkpoint.NewGitStore(repo)
1011	
1012		summary, err := store.ReadCommitted(ctx, checkpointID)
1013		if err != nil {
1014			return fmt.Errorf("reading checkpoint summary: %w", err)
1015		}
1016		if summary == nil || len(summary.Sessions) <= 1 {
1017			return nil
1018		}
1019	
1020		// Collect union of files_touched from sessions that had real checkpoints (SaveStep ran).
1021		// Sessions with checkpoints_count == 0 (e.g., commit-only sessions) use a fallback that
1022		// includes ALL committed files, which would incorrectly classify human-created files as agent work.
1023		agentFiles := make(map[string]struct{})
1024		for i := range len(summary.Sessions) {
1025			metadata, readErr := store.ReadSessionMetadata(ctx, checkpointID, i)
1026			if readErr != nil || metadata == nil {
1027				continue
1028			}
1029			if metadata.CheckpointsCount == 0 {
1030				continue // Skip sessions that used the filesTouched fallback
1031			}
1032			for _, f := range metadata.FilesTouched {
1033				agentFiles[f] = struct{}{}
1034			}
1035		}
1036	
1037		if len(agentFiles) == 0 {
1038			return nil
1039		}
1040	
1041		// Get all files changed in this commit (parent → HEAD)
1042		allChangedFiles, err := getAllChangedFiles(ctx, parentTree, headTree, repoDir, "", "")
1043		if err != nil {
1044			logging.Warn(logCtx, "combined attribution: failed to enumerate changed files",
1045				slog.String("error", err.Error()))
1046			return nil
1047		}
1048	
1049		// Classify each changed file as agent or human and count lines
1050		var agentAdded, agentRemoved, humanAdded, humanRemoved int
1051		for _, filePath := range allChangedFiles {
1052			// Skip CLI/agent config metadata — not human or agent code work
1053			if strings.HasPrefix(filePath, ".entire/") || strings.HasPrefix(filePath, paths.EntireMetadataDir+"/") ||
1054				strings.HasPrefix(filePath, ".claude/") {
1055				continue
1056			}
1057	
1058			parentContent := getFileContent(parentTree, filePath)
1059			headContent := getFileContent(headTree, filePath)
1060			_, added, removed := diffLines(parentContent, headContent)
1061	
1062			if _, isAgent := agentFiles[filePath]; isAgent {
1063				agentAdded += added
1064				agentRemoved += removed
